// ─────────────────────────────────────────────
// ⚙️  CONFIGURE AQUI
// ─────────────────────────────────────────────
const PROXMOX_HOST = 'https://proxmox.local:8006'; // IP/host do seu Proxmox
const NODE_NAME    = 'pve';                       // nome do nó (padrão: pve)
// ─────────────────────────────────────────────

const raw  = $input.first().json;
const body = raw.body || raw;

const action        = (body.action || 'status').toLowerCase().trim();
const vmid          = body.vmid != null ? String(body.vmid).trim() : null;

// stop usa shutdown (desliga pelo sistema operacional); status/stop seria tirar da tomada
const actionMap     = { start: 'start', stop: 'shutdown', restart: 'reboot' };
const proxmoxAction = actionMap[action] || null;

return [{ json: { host: PROXMOX_HOST, node: NODE_NAME, action, proxmoxAction, vmid } }];

const raw = $input.first().json;
const d = raw?.data || raw?.body?.data || null;

if (!d || raw.error) {
  return [{ json: { nodeStatus: null, nodeStatusOk: false } }];
}

const cpuPct  = Math.round((d.cpu || 0) * 100);
const memUsed = Math.round((d.memory?.used  || 0) / 1024 / 1024 / 1024 * 100) / 100;
const memTotal= Math.round((d.memory?.total || 0) / 1024 / 1024 / 1024 * 100) / 100;
const memPct  = memTotal > 0 ? Math.round(memUsed / memTotal * 100) : 0;

const uptimeSec = d.uptime || 0;
const days  = Math.floor(uptimeSec / 86400);
const hours = Math.floor((uptimeSec % 86400) / 3600);
const mins  = Math.floor((uptimeSec % 3600) / 60);
const uptimeStr = days > 0 ? `${days}d ${hours}h ${mins}m` : `${hours}h ${mins}m`;

const load = (d.loadavg || []).map(v => parseFloat(v).toFixed(2)).join(' / ');

return [{ json: {
  nodeStatus: { cpuPct, memUsed, memTotal, memPct, uptime: uptimeStr, load },
  nodeStatusOk: true
}}];

const raw = $input.first().json;
const list = raw?.data || raw?.body?.data || [];

if (!Array.isArray(list) || list.length === 0) {
  return [{ json: { rrdCpuPct: null, rrdOk: false } }];
}

const validPoints = list
  .filter(p => p.cpu != null && !isNaN(p.cpu))
  .slice(-5);

if (validPoints.length === 0) {
  return [{ json: { rrdCpuPct: null, rrdOk: false } }];
}

const avgCpu    = validPoints.reduce((sum, p) => sum + p.cpu, 0) / validPoints.length;
const rrdCpuPct = Math.round(avgCpu * 100);

return [{ json: { rrdCpuPct, rrdOk: true, rrdSamples: validPoints.length } }];

const raw = $input.first().json;
const list = raw?.data || raw?.body?.data || [];

if (!Array.isArray(list)) {
  return [{ json: { vms: [], vmsOk: false } }];
}

const statusEmoji = (s) => s === 'running' ? '🟢' : s === 'stopped' ? '🔴' : '🟡';

const vms = list
  .sort((a, b) => a.vmid - b.vmid)
  .map(vm => ({
    id:       vm.vmid,
    name:     vm.name || `vm-${vm.vmid}`,
    status:   vm.status,
    emoji:    statusEmoji(vm.status),
    cpus:     vm.cpus || 0,
    memMB:    Math.round((vm.mem    || 0) / 1024 / 1024),
    maxMemMB: Math.round((vm.maxmem || 0) / 1024 / 1024),
    uptime:   vm.uptime || 0
  }));

return [{ json: { vms, vmsOk: true } }];

const raw = $input.first().json;
const list = raw?.data || raw?.body?.data || [];

if (!Array.isArray(list)) {
  return [{ json: { lxcs: [], lxcsOk: false } }];
}

const statusEmoji = (s) => s === 'running' ? '🟢' : s === 'stopped' ? '🔴' : '🟡';

const lxcs = list
  .sort((a, b) => a.vmid - b.vmid)
  .map(ct => ({
    id:       ct.vmid,
    name:     ct.name || `ct-${ct.vmid}`,
    status:   ct.status,
    emoji:    statusEmoji(ct.status),
    cpus:     ct.cpus || 0,
    memMB:    Math.round((ct.mem    || 0) / 1024 / 1024),
    maxMemMB: Math.round((ct.maxmem || 0) / 1024 / 1024),
    uptime:   ct.uptime || 0
  }));

return [{ json: { lxcs, lxcsOk: true } }];

const raw = $input.first().json;
const list = raw?.data || raw?.body?.data || [];

if (!Array.isArray(list)) {
  return [{ json: { storages: [], storagesOk: false } }];
}

const storages = list
  .filter(s => s.active)
  .map(s => {
    const usedGB  = Math.round((s.used  || 0) / 1024 / 1024 / 1024 * 100) / 100;
    const totalGB = Math.round((s.total || 0) / 1024 / 1024 / 1024 * 100) / 100;
    const pct     = totalGB > 0 ? Math.round(usedGB / totalGB * 100) : 0;
    const bar     = '█'.repeat(Math.round(pct / 10)) + '░'.repeat(10 - Math.round(pct / 10));
    return { name: s.storage, type: s.type, usedGB, totalGB, pct, bar };
  });

return [{ json: { storages, storagesOk: true } }];

const items = $input.all();

let nodeStatus = null, nodeStatusOk = false;
let rrdCpuPct  = null, rrdOk = false, rrdSamples = 0;
let vms = [],          vmsOk = false;
let lxcs = [],         lxcsOk = false;
let storages = [],     storagesOk = false;

for (const item of items) {
  const j = item.json;
  if (j.nodeStatus !== undefined) { nodeStatus = j.nodeStatus; nodeStatusOk = j.nodeStatusOk; }
  if (j.rrdCpuPct  !== undefined) { rrdCpuPct = j.rrdCpuPct; rrdOk = j.rrdOk; rrdSamples = j.rrdSamples || 0; }
  if (j.vms        !== undefined) { vms = j.vms; vmsOk = j.vmsOk; }
  if (j.lxcs       !== undefined) { lxcs = j.lxcs; lxcsOk = j.lxcsOk; }
  if (j.storages   !== undefined) { storages = j.storages; storagesOk = j.storagesOk; }
}

const ts = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

// ── HOST STATUS ──────────────────────────────
let hostBlock = '';
if (nodeStatus && nodeStatusOk) {
  const cpuPct   = (rrdOk && rrdCpuPct !== null) ? rrdCpuPct : nodeStatus.cpuPct;
  const cpuLabel = (rrdOk && rrdCpuPct !== null)
    ? `**${cpuPct}%** _(${rrdSamples}min)_`
    : `**${cpuPct}%**`;
  const cpuBar   = '█'.repeat(Math.round(cpuPct / 10)) + '░'.repeat(10 - Math.round(cpuPct / 10));
  const memBar   = '█'.repeat(Math.round(nodeStatus.memPct / 10)) + '░'.repeat(10 - Math.round(nodeStatus.memPct / 10));
  const cpuEmoji = cpuPct > 85 ? '🔴' : cpuPct > 60 ? '🟠' : '🟢';
  const memEmoji = nodeStatus.memPct > 85 ? '🔴' : nodeStatus.memPct > 60 ? '🟠' : '🟢';
  hostBlock = `🖥️ **Host Status**\n> ${cpuEmoji} CPU: \`${cpuBar}\` ${cpuLabel}\n> ${memEmoji} RAM: \`${memBar}\` **${nodeStatus.memPct}%** (${nodeStatus.memUsed}/${nodeStatus.memTotal} GB)\n> ⏱️ Uptime: **${nodeStatus.uptime}** | Load: \`${nodeStatus.load}\``;
} else {
  hostBlock = '🖥️ **Host Status** — ❌ Dados indisponíveis';
}

// ── VMs ──────────────────────────────────────
let vmsBlock = '';
if (vmsOk && vms.length > 0) {
  const running = vms.filter(v => v.status === 'running').length;
  const vmLines = vms.map(v => {
    const mem = v.status === 'running' ? ` | RAM: ${v.memMB}/${v.maxMemMB} MB` : '';
    return `> ${v.emoji} \`${v.id}\` **${v.name}** — ${v.status}${mem}`;
  }).join('\n');
  vmsBlock = `🖥️ **VMs** (${running}/${vms.length} running)\n${vmLines}`;
} else if (vmsOk && vms.length === 0) {
  vmsBlock = '🖥️ **VMs** — Nenhuma VM encontrada';
} else {
  vmsBlock = '🖥️ **VMs** — ❌ Dados indisponíveis';
}

// ── LXCs ─────────────────────────────────────
let lxcsBlock = '';
if (lxcsOk && lxcs.length > 0) {
  const running = lxcs.filter(c => c.status === 'running').length;
  const ctLines = lxcs.map(c => {
    const mem = c.status === 'running' ? ` | RAM: ${c.memMB}/${c.maxMemMB} MB` : '';
    return `> ${c.emoji} \`${c.id}\` **${c.name}** — ${c.status}${mem}`;
  }).join('\n');
  lxcsBlock = `📦 **LXC Containers** (${running}/${lxcs.length} running)\n${ctLines}`;
} else if (lxcsOk && lxcs.length === 0) {
  lxcsBlock = '📦 **LXC Containers** — Nenhum container encontrado';
} else {
  lxcsBlock = '📦 **LXC Containers** — ❌ Dados indisponíveis';
}

// ── Storage ───────────────────────────────────
let storageBlock = '';
if (storagesOk && storages.length > 0) {
  const stLines = storages.map(s => {
    const emoji = s.pct > 85 ? '🔴' : s.pct > 60 ? '🟠' : '🟢';
    return `> ${emoji} **${s.name}** (${s.type}): \`${s.bar}\` ${s.pct}% — ${s.usedGB}/${s.totalGB} GB`;
  }).join('\n');
  storageBlock = `💾 **Storage**\n${stLines}`;
} else {
  storageBlock = '💾 **Storage** — ❌ Dados indisponíveis';
}

const report = [
  `🗓️ **Proxmox Dashboard** — \`${ts}\``,
  '', hostBlock,
  '', vmsBlock,
  '', lxcsBlock,
  '', storageBlock
].join('\n').trim();

return [{ json: { report } }];

const raw  = $input.first().json;
const data = raw?.data || raw?.body?.data;
return [{ json: { vmList: Array.isArray(data) ? data : [], vmListOk: Array.isArray(data) } }];

const raw  = $input.first().json;
const data = raw?.data || raw?.body?.data;
return [{ json: { lxcList: Array.isArray(data) ? data : [], lxcListOk: Array.isArray(data) } }];

const items = $input.all();
let vmList = [], lxcList = [];
let vmListOk = false, lxcListOk = false;

for (const item of items) {
  const j = item.json;
  if (j.vmList  !== undefined) { vmList  = j.vmList;  vmListOk  = j.vmListOk; }
  if (j.lxcList !== undefined) { lxcList = j.lxcList; lxcListOk = j.lxcListOk; }
}

const config        = $('Config').first().json;
const { vmid, action, proxmoxAction, host, node } = config;

// Erro vira resposta em vez de throw: com throw o workflow falha antes do
// Respond, o n8n devolve um erro genérico e a mensagem nunca chega no Discord.
const falha = (msg) => [{ json: { found: false, report: `❌ ${msg}` } }];

if (!vmid) {
  return falha('vmid é obrigatório. Use: `!proxmox start 103`');
}

if (!proxmoxAction) {
  return falha(`Ação inválida: "${action}". Use: start, stop ou restart`);
}

if (!vmListOk && !lxcListOk) {
  return falha('Não consegui listar VMs e containers no Proxmox. Verifique o host e a credencial no n8n.');
}

const vmMatch  = vmList.find(v => String(v.vmid)  === String(vmid));
const lxcMatch = lxcList.find(c => String(c.vmid) === String(vmid));

if (!vmMatch && !lxcMatch) {
  return falha(`ID \`${vmid}\` não encontrado. Veja os IDs com \`!proxmox\``);
}

const type          = vmMatch ? 'qemu' : 'lxc';
const guest         = vmMatch || lxcMatch;
const guestName     = guest.name || `id-${vmid}`;
const currentStatus = guest.status;

return [{ json: { found: true, type, vmid, name: guestName, currentStatus, action, proxmoxAction, host, node } }];

const raw = $input.first().json;
const ctx = $('Detect Type').first().json;

const actionEmoji = { start: '▶️', stop: '⏹️', restart: '🔄' };
const emoji       = actionEmoji[ctx.action] || '⚙️';
const typeLabel   = ctx.type === 'qemu' ? '🖥️ VM' : '📦 LXC';
const actionPT    = {
  start:   'iniciado com sucesso!',
  stop:    'desligando pelo sistema operacional…',
  restart: 'reiniciado com sucesso!',
};
const resultado   = actionPT[ctx.action] || `${ctx.action} executado`;

// Proxmox retorna string UPID em caso de sucesso
const upid    = raw?.data || raw?.body?.data;
const success = upid && typeof upid === 'string' && upid.startsWith('UPID:');

let report;
if (success) {
  report = `${emoji} ${typeLabel} **${ctx.name}** (\`${ctx.vmid}\`) ${resultado}\n> ✅ Tarefa registrada no Proxmox`;
} else {
  const errMsg = raw?.message || raw?.body?.message || 'verifique o estado do container/VM';
  report = `❌ Falha ao executar **${ctx.action}** em **${ctx.name}** (\`${ctx.vmid}\`)\n> ${errMsg}`;
}

return [{ json: { report } }];
